	def _is_cache_valid(A):
		'Check if cached auth is still valid'
		if not A._state.get(_D):return False
		B=datetime.fromisoformat(A._state[_D]);C=A._state.get(_G,60);D=B+timedelta(minutes=C);return datetime.now()<D
